spec.setup_code:
var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.position.x = Math.sin(t * 0.02) * 2;
                    cube.rotation.y = t * 0.02;
                  }
                };

var path = [];
                return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var startX = W * 0.2, startY = H * 0.5;
                    var radius = Math.min(W, H) * 0.28;
                    var angle = (t * 0.02) % (Math.PI * 1.5);
                    var x = startX + Math.sin(angle) * radius;
                    var y = startY - (1 - Math.cos(angle)) * radius;
                    path.push([x, y]);
                    if (path.length > 400) path.shift();
                    ctx.strokeStyle = '#E8593C';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    for (var i = 0; i < path.length; i++) {
                      if (i === 0) ctx.moveTo(path[i][0], path[i][1]);
                      else ctx.lineTo(path[i][0], path[i][1]);
                    }
                    ctx.stroke();
                    ctx.strokeStyle = '#3C7CE8';
                    ctx.lineWidth = 2;
                    ctx.setLineDash([6, 6]);
                    ctx.beginPath();
                    ctx.moveTo(startX, startY);
                    ctx.lineTo(x, y);
                    ctx.stroke();
                    ctx.setLineDash([]);
                    ctx.fillStyle = '#333333';
                    ctx.beginPath();
                    ctx.arc(startX, startY, 5, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 8, 0, Math.PI * 2);
                    ctx.fill();
                  }
                };
